package com.termux.app.workspace;
import android.app.*;import android.graphics.drawable.*;import android.view.*;import java.lang.reflect.*;import java.util.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28)
public class TerminalBorderCallbackTest {
 void style(View button)throws Exception{Method m=WorkspaceRipple.class.getDeclaredMethod("styleTree",View.class,WeakHashMap.class);m.setAccessible(true);m.invoke(null,button,new WeakHashMap<View,Drawable>());}
 @Test public void oldWrappingOfCurrentBackgroundDisconnectsTheScheduledBorder()throws Exception{Activity a=Robolectric.buildActivity(Activity.class).setup().get();WorkspaceIconButton b=WorkspaceDialogs.headerButton(a,com.termux.R.drawable.workspace_terminal,"Terminal",()->{});WorkspaceTransferBorder border=new WorkspaceTransferBorder(1,true);LayerDrawable content=new LayerDrawable(new Drawable[]{b.getBackground(),border});b.setBackground(content);assertSame(b,content.getCallback());style(b);assertTrue(b.getBackground() instanceof RippleDrawable);assertNull("View detached its old background after it was reused inside the new ripple",content.getCallback());}
 @Test public void oneRippleRootKeepsTheEntireBorderCallbackChainConnected()throws Exception{Activity a=Robolectric.buildActivity(Activity.class).setup().get();WorkspaceIconButton b=WorkspaceDialogs.headerButton(a,com.termux.R.drawable.workspace_terminal,"Terminal",()->{});WorkspaceTransferBorder border=new WorkspaceTransferBorder(1,true);WorkspaceDialogs.headerAttention(b,border);Drawable root=b.getBackground();style(b);style(b);assertSame(root,b.getBackground());Drawable current=border;int depth=0;while(current.getCallback() instanceof Drawable){current=(Drawable)current.getCallback();assertTrue(++depth<6);}assertSame(root,current);assertSame(b,current.getCallback());assertEquals(1,b.getAlpha(),.001);border.active(false);}
}
